				for (const src of [`${ORYVEX_REPO_RAW}flags/${fm[1]}/${fm[2]}.svg`, `https://cdn.jsdelivr.net/gh/lipis/flag-icons@7.3.2/flags/${fm[1]}/${fm[2]}.svg`]) {
					try { const fr = await fetch(src); if (fr.ok) { svg = await fr.text(); break; } } catch (e) {}
				}
