const OXA_SCRIPT = `
		function oxaPeek(id, btn) {
			const input = document.getElementById(id);
			if (!input) return;
			const show = input.type === 'password';
			input.type = show ? 'text' : 'password';
			btn.querySelector('.oxa-eye-open').classList.toggle('hidden', show);
			btn.querySelector('.oxa-eye-shut').classList.toggle('hidden', !show);
			btn.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
			btn.title = show ? 'Hide password' : 'Show password';
		}
		function oxaBusy(btn, busy, label) {
			if (!btn) return;
			btn.disabled = !!busy;
			const text = btn.querySelector('.oxa-label');
			const spin = btn.querySelector('.oxa-spin');
			if (text && label) text.textContent = label;
			if (spin) spin.classList.toggle('hidden', !busy);
		}
		function oxaSay(id, message, ok) {
			const el = document.getElementById(id);
			if (!el) return;
			let msg = message ? String(message) : '';
			if (/d1/i.test(msg) && /limit|exceeded|daily row/i.test(msg)) msg = 'Your D1 database quota is used up. It resets daily at 00:00 UTC.';
			el.textContent = msg.replace(/^[\\u2700-\\u27BF\\uE000-\\uF8FF\\u2600-\\u26FF\\uFE0F\\s]+/, '');
			el.classList.toggle('hidden', !msg);
			el.classList.toggle('text-red-600', !ok);
			el.classList.toggle('dark:text-red-400', !ok);
			el.classList.toggle('text-green-600', !!ok);
			el.classList.toggle('dark:text-green-400', !!ok);
		}
		function oxaBad(input, bad) {
			if (!input) return;
			input.classList.toggle('border-red-500', !!bad);
			input.classList.toggle('dark:border-red-500', !!bad);
		}
`;
