		function attachHoldButtonAction(btn, prog, durationMs, onTrigger) {
			if (!btn) return;
			let startTime = 0, animFrame = null, holding = false, fired = false, activePointer = null;
			const reset = () => { holding = false; activePointer = null; cancelAnimationFrame(animFrame); if (prog) { prog.style.transition = 'width .25s ease'; prog.style.width = '0%'; } btn.style.transform = 'scale(1)'; };
			const tick = (time) => {
				if (!holding) return;
				const elapsed = time - startTime;
				if (prog) prog.style.width = Math.min(elapsed / durationMs * 100, 100) + '%';
				if (elapsed >= durationMs) { if (!fired) { fired = true; reset(); if (onTrigger) onTrigger(); } return; }
				animFrame = requestAnimationFrame(tick);
			};
			btn.addEventListener('pointerdown', (e) => {
				if (fired || holding) return;
				if (e.pointerType === 'mouse' && e.button !== 0) return;
				e.preventDefault();
				holding = true; activePointer = e.pointerId;
				try { btn.setPointerCapture(e.pointerId); } catch (err) {}
				if (prog) prog.style.transition = 'none';
				startTime = performance.now();
				btn.style.transform = 'scale(0.97)';
				animFrame = requestAnimationFrame(tick);
			});
			['pointerup', 'pointercancel', 'lostpointercapture'].forEach((ev) => btn.addEventListener(ev, (e) => { if (holding && (activePointer === null || e.pointerId === activePointer)) reset(); }));
			btn.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); });
			btn.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') e.preventDefault(); });
			btn.addEventListener('contextmenu', (e) => e.preventDefault());
		}
	async function checkGlobalMessage() {
		try {
			const res = await fetchWithFallbackUI('message.txt?t=' + Date.now());
			if (!res || !res.ok) { checkLoopWarning(); return; }
			const text = await res.text();
			const lines = text.split('\\n');
			if (lines.length < 2) { checkLoopWarning(); return; }
			const firstLine = lines[0].trim();
			if (!firstLine.startsWith('VERSION=')) { checkLoopWarning(); return; }
			const version = firstLine.split('=')[1].trim();
			const content = lines.slice(1).join('\\n').trim();
			let seenVersion = window.oryvex_global_msg_version;
			try { seenVersion = seenVersion || localStorage.getItem('oryvex-msg-seen'); } catch (e) {}
			if (seenVersion !== version) {
				document.getElementById('global-message-content').innerHTML = content;
				setModalState('global-message-modal', true);
				const oldBtn = document.getElementById('global-message-close-btn');
				const newBtn = oldBtn.cloneNode(true);
				oldBtn.parentNode.replaceChild(newBtn, oldBtn);
				const btn = document.getElementById('global-message-close-btn');
				const prog = document.getElementById('global-message-progress');
				attachHoldButtonAction(btn, prog, 1000, () => {
					setModalState('global-message-modal', false);
					window.oryvex_global_msg_version = version;
					try { localStorage.setItem('oryvex-msg-seen', version); } catch (e) {}
					setTimeout(() => checkLoopWarning(), 500);
				});
			} else {
				checkLoopWarning(); 
			}
		} catch (err) {}
	}
