		async function checkForUpdates(isManual = false) {
			const btn = document.getElementById('update-toggle');
			const badge = document.getElementById('update-badge');
			try {
				if (isManual && btn) { if (btn.classList.contains('ox-checking')) return; btn.classList.add('ox-checking'); btn.setAttribute('aria-busy','true'); }
				let latest = null;
				const okVer = function(t) { return /^[0-9]+[.][0-9]+[.][0-9]+$/.test(t) ? t : null; };
				const res = await fetchWithFallbackUI('version.txt?t=' + Date.now());
				if (res.ok) latest = okVer((await res.text()).trim());
				if (!latest) {
					const r2 = await fetchWithFallbackUI('Source.js?t=' + Date.now());
					if (r2.ok) { const parts = (await r2.text()).split("CURRENT_VERSION = '"); if (parts[1]) latest = okVer(parts[1].split("'")[0]); }
				}
				if (btn) { btn.classList.remove('ox-checking'); btn.removeAttribute('aria-busy'); }
				if (!latest) throw new Error('no version');
				const cmp = oxCmpVer(latest, CURRENT_VERSION);
				if (cmp > 0) {
					if (btn) { btn.classList.add('ox-update-ready'); btn.title = 'Update available: v' + latest; }
					if (badge) badge.classList.remove('hidden');
					if (window.autoUpdateStatusCache && !isManual) {
						const lastUp = parseInt(sessionStorage.getItem('oryvex_last_update') || '0', 10);
						if (Date.now() - lastUp < 180000) return;
						showToast('New version found. Updating automatically...');
						await applyUpdate();
						return;
					}
					if (isManual) toggleUpdateModal(true, latest);
				} else {
					if (btn) { btn.classList.remove('ox-update-ready'); btn.title = 'Up to date (v' + CURRENT_VERSION + ')'; }
					if (badge) badge.classList.add('hidden');
					if (isManual) {
						if (cmp === 0) oxOk('You are on the latest version (v' + CURRENT_VERSION + ').');
						else oxInfo('This build (v' + CURRENT_VERSION + ') is newer than the repository (v' + latest + ').');
					}
				}
			} catch (err) {
				if (btn) { btn.classList.remove('ox-checking'); btn.removeAttribute('aria-busy'); }
				if (isManual) oxErr('Could not check for updates. Please follow the manual update guide.');
			}
		}
